# tools/interview_gen/gen_aiml.py
# 40 Advanced Placement-Grade AI & Machine Learning Questions (iv-aiml-101 to iv-aiml-140)

from .common import make_tech_ans

def get_aiml_questions():
    qs = {}
    data = [
        ("iv-aiml-101", "AI & Machine Learning", "Intermediate", "Google",
         "Explain the mathematical connection between Singular Value Decomposition (SVD) and Principal Component Analysis (PCA).",
         "PCA finds orthogonal directions (principal components) of maximal variance in data; SVD is the matrix factorization technique that computes PCA efficiently without calculating the full covariance matrix.",
         "Given a zero-centered data matrix X of dimensions (N x D):<br>1. Sample Covariance Matrix is C = (1 / N) * X^T * X (size D x D). PCA computes the eigenvectors of C.<br>2. SVD factorizes X directly: X = U * Sigma * V^T, where U is (N x N) orthonormal left singular vectors, Sigma is (N x D) diagonal singular values, and V is (D x D) orthonormal right singular vectors.<br>Mathematical Connection: C = (1 / N) * (V * Sigma^T * U^T) * (U * Sigma * V^T) = V * (Sigma^2 / N) * V^T (since U^T * U = I). This proves that the right singular vectors V of X are IDENTICAL to the principal component eigenvectors of covariance matrix C, and the eigenvalues are lambda_i = sigma_i^2 / N.<br>Computational benefit: Computing SVD directly on X via Golub-Reinsch algorithm avoids explicitly computing and squaring the covariance matrix C, which prevents catastrophic numerical precision loss.",
         "Always center the data (subtract feature means) before applying PCA; uncentered data produces false first principal components pointing toward the dataset mean."),

        ("iv-aiml-102", "AI & Machine Learning", "Fresher", "Amazon",
         "Explain the Bias-Variance Trade-off and how L1 (Lasso) versus L2 (Ridge) Regularization control model complexity.",
         "Total expected generalization error decomposes into three additive components: Error = Bias^2 + Variance + Irreducible Noise.",
         "1. Bias: Error introduced by approximating a complex real-world phenomenon with an overly simplistic model (Underfitting).<br>2. Variance: Model's sensitivity to small fluctuations in training data; model learns training noise (Overfitting).<br>Regularization adds a penalty term to the loss function to constrain weights: Loss = MSE + lambda * Penalty.<br>- L2 Regularization (Ridge): Penalty = Sum(w_i^2). Drives weights smoothly toward zero (weight decay) but rarely to absolute zero. Effective when many collinear features share predictive signal.<br>- L1 Regularization (Lasso): Penalty = Sum(|w_i|). Because the L1 constraint region is a diamond with sharp corners on coordinate axes, gradient descent contours intersect at corners where weights are set to EXACTLY ZERO. Lasso performs automated feature selection, producing sparse models.",
         "Elastic Net combines both: Penalty = alpha * L1 + (1 - alpha) * L2, overcoming Lasso's limitation of selecting at most n features when p > n."),

        ("iv-aiml-103", "AI & Machine Learning", "Intermediate", "Meta",
         "Compare Random Forest with Gradient Boosted Decision Trees (XGBoost / LightGBM) in terms of bagging vs boosting.",
         "Random Forest and GBDT are both ensemble tree methods, but differ fundamentally in how individual trees are trained and combined.",
         "1. Random Forest (Bagging - Bootstrap Aggregating): Trains multiple deep, high-variance decision trees in PARALLEL on random bootstrap subsets of data and random feature subsets. Predictions are averaged (regression) or voted (classification). Primary goal: REDUCE VARIANCE without increasing bias. Robust against overfitting and outliers; easy to tune.<br>2. Gradient Boosted Trees (Boosting): Trains shallow, high-bias trees (weak learners) SEQUENTIALLY. Each new tree fits the pseudo-residuals (negative gradient of the loss function) of the previous ensemble. Primary goal: REDUCE BIAS.<br>XGBoost Innovations: Adds 2nd-order Taylor expansion gradients (hessians), exact greedy/approximate split finding, L1/L2 tree complexity regularization, and sparsity-aware split finding.<br>LightGBM Innovations: Uses Histogram-based algorithms, Gradient-based One-Side Sampling (GOSS), and Exclusive Feature Bundling (EFB) to run 10x to 15x faster with 1/5th memory.",
         "Rule: Random Forest reduces variance in parallel; Gradient Boosting reduces bias sequentially."),

        ("iv-aiml-104", "AI & Machine Learning", "Intermediate", "Microsoft",
         "Explain Maximum Likelihood Estimation (MLE) versus Maximum A Posteriori (MAP) estimation.",
         "Both are fundamental statistical frameworks for estimating model parameters theta from observed data X.",
         "1. Maximum Likelihood Estimation (MLE): Chooses parameters theta that maximize the probability of observing the data: theta_MLE = argmax P(X | theta) = argmax Sum log P(x_i | theta). Assumes all parameter values are equally probable a priori (uniform prior). Highly prone to overfitting on small sample sizes.<br>2. Maximum A Posteriori (MAP): Incorporates prior beliefs about parameter distribution using Bayes' theorem: P(theta | X) = (P(X | theta) * P(theta)) / P(X). Therefore: theta_MAP = argmax [ log P(X | theta) + log P(theta) ].<br>Crucial Equivalence: Regularization is mathematically equivalent to MAP estimation with specific priors!<br>- MAP with a Zero-Mean Gaussian Prior P(theta) ~ N(0, sigma^2) is mathematically identical to L2 (Ridge) Regularization!<br>- MAP with a Zero-Mean Laplacian Prior P(theta) ~ Laplace(0, b) is mathematically identical to L1 (Lasso) Regularization!",
         "As dataset size N approaches infinity, the likelihood overwhelms the prior, and theta_MAP converges to theta_MLE."),

        ("iv-aiml-105", "AI & Machine Learning", "Fresher", "Apple",
         "When should you use ROC-AUC versus Precision-Recall (PR) AUC for evaluating binary classification models?",
         "ROC-AUC and PR-AUC measure classifier performance across all decision thresholds, but behave dramatically differently under class imbalance.",
         "1. ROC Curve: Plots True Positive Rate (Recall = TP / (TP + FN)) versus False Positive Rate (FPR = FP / (FP + TN)). Notice the denominator of FPR contains True Negatives (TN). In heavy class imbalance (e.g., fraud detection with 99.9% negative transactions), the massive TN count keeps FPR very small even if hundreds of false positives occur. A model can have an impressively high ROC-AUC of 0.98 while producing terrible real-world fraud predictions!<br>2. Precision-Recall Curve: Plots Precision (TP / (TP + FP)) versus Recall (TP / (TP + FN)). Neither axis contains True Negatives (TN). If the model predicts many false positives, Precision drops immediately, reflecting true operational performance.<br>Rule: Use ROC-AUC for balanced datasets; use Precision-Recall AUC (PR-AUC) whenever evaluating rare-event detection, fraud, medical diagnosis, or severe class imbalance.",
         "A random guess classifier has a baseline ROC-AUC of 0.5; on PR-AUC, a random classifier's baseline equals the positive class prevalence (e.g., 0.001 for 0.1% fraud)."),

        ("iv-aiml-106", "AI & Machine Learning", "Intermediate", "Nvidia",
         "What causes the Vanishing and Exploding Gradient problems in deep neural networks, and how do modern architectures solve them?",
         "During backpropagation, gradients are computed via the chain rule by multiplying weight matrices and activation derivatives layer-by-layer: dL/dw_1 = dL/dy * Product(W_l * sigma'(z_l)).",
         "1. Vanishing Gradients: When using saturating activation functions (Sigmoid, Tanh), their derivatives are bounded: max(sigma') = 0.25 for sigmoid. Multiplying values < 0.25 across 20+ layers causes gradients to decay exponentially toward zero as they propagate back to early layers. Front layers stop learning.<br>2. Exploding Gradients: If weights are initialized too large (eigenvalues > 1.0), multiplying weight matrices across deep networks causes gradients to explode exponentially to NaN / Infinity, causing numerical instability.<br>Architectural Solutions:<br>- Activation Functions: Non-saturating activations like ReLU (`f(x) = max(0, x)`), LeakyReLU, GELU maintain a derivative of 1.0 for positive inputs.<br>- Weight Initialization: He (Kaiming) initialization for ReLU; Xavier/Glorot for Sigmoid/Tanh.<br>- Residual Connections (ResNet): Highway connections `y = F(x) + x` allow gradients to flow back directly through the identity addition term with derivative +1, enabling networks with 1,000+ layers to train smoothly.<br>- Normalization: Batch Normalization and Layer Normalization clamp intermediate activations.",
         "Gradient clipping (`clip_grad_norm`) is also used in RNNs/LLMs to place a hard upper ceiling on gradient magnitude."),

        ("iv-aiml-107", "AI & Machine Learning", "Intermediate", "Google",
         "Explain the Transformer Self-Attention mechanism: Derive Scaled Dot-Product Attention and explain why scaling by sqrt(d_k) is mandatory.",
         "Self-attention allows tokens in a sequence to dynamically attend to and weigh the importance of all other tokens in the context window.",
         "Given input embeddings X, linear projections produce three matrices: Queries (Q = X*W_q), Keys (K = X*W_k), and Values (V = X*W_v) of dimension d_k.<br>Formula: Attention(Q, K, V) = softmax( (Q * K^T) / sqrt(d_k) ) * V.<br>Why scaling by sqrt(d_k) is mandatory:<br>Assume elements of Q and K are independent random variables with zero mean and unit variance (mean = 0, var = 1). The dot product q . k = Sum(q_i * k_i) is the sum of d_k independent terms. By variance properties: Var(Sum X_i) = Sum Var(X_i) = d_k, meaning standard deviation is sqrt(d_k). For large d_k (e.g., d_k = 64 or 128), dot products grow extremely large in magnitude.<br>When large values enter the softmax function, the softmax outputs saturate into regions with near-zero gradients (resembling one-hot distributions). Backpropagating through saturated softmax causes vanishing gradients! Dividing by sqrt(d_k) normalizes variance back to 1.0, preserving healthy gradients throughout training.",
         "Multi-Head Attention projects Q, K, V into h distinct lower-dimensional subspaces, allowing the model to attend to information from different representation subspaces simultaneously."),

        ("iv-aiml-108", "AI & Machine Learning", "Advanced", "OpenAI",
         "What is Rotary Position Embedding (RoPE) and why has it replaced Absolute Sinusoidal Encodings in modern LLMs (Llama, Mistral)?",
         "Transformers are permutation-invariant; they need positional information to distinguish token order ('dog bites man' vs 'man bites dog').",
         "Limitations of Absolute Embeddings: Adding a fixed vector P_i to token embedding X_i represents absolute position, but attention depends fundamentally on RELATIVE token distances (m - n). Absolute embeddings generalize poorly to context lengths longer than seen in training.<br>RoPE Innovation (Su et al.): Instead of adding positional vectors to embeddings, RoPE encodes position by ROTATING query and key vectors in complex 2D planes by an angle proportional to their sequence index m:<br>For a 2D chunk: R_Theta,m * q_m = [ [cos(m*theta), -sin(m*theta)], [sin(m*theta), cos(m*theta)] ] * [q1, q2]^T.<br>Key Mathematical Beauty: When computing attention dot product: (R_m * q)^T * (R_n * k) = q^T * (R_m^T * R_n) * k = q^T * R_(n - m) * k. The dot product depends SOLELY on the relative offset (n - m)!<br>Benefits: 1. Preserves vector norm (rotation doesn't change length). 2. Attention naturally decays with distance. 3. Enables context extension techniques (NTK-aware scaling, YaRN) to expand context from 4k to 128k+ tokens without full retraining.",
         "RoPE is the de facto standard positional encoding across virtually all top open-weight foundation models."),

        ("iv-aiml-109", "AI & Machine Learning", "Intermediate", "Anthropic",
         "Explain LoRA (Low-Rank Adaptation) and QLoRA for parameter-efficient fine-tuning (PEFT) of Large Language Models.",
         "Full fine-tuning of a 70B parameter LLM requires updating all 70B weights, demanding hundreds of gigabytes of VRAM for Adam optimizer states (16 bytes per parameter) and massive compute clusters.",
         "1. LoRA Hypothesis (Aghajanyan et al.): The weight updates Delta_W during downstream adaptation have a low 'intrinsic dimension'.<br>Mechanism: Freeze pre-trained weight matrix W_0 (dimension d x k). Represent the weight update Delta_W as the product of two low-rank matrices: Delta_W = B * A, where A is (r x k) and B is (d x r), with rank r << min(d, k) (e.g., r = 8 or 16).<br>- Matrix A is initialized randomly with Gaussian distribution; B is initialized to zero (so Delta_W = 0 at start of training).<br>- Forward pass: h = W_0 * x + (alpha / r) * (B * A * x).<br>- During training, ONLY A and B are updated (less than 0.5% of total model parameters!). Cuts optimizer memory footprint by 75%+.<br>- At inference: B * A can be mathematically added directly back into W_0 (`W_new = W_0 + B*A`), resulting in ZERO extra inference latency!<br>2. QLoRA: Quantizes the frozen base model W_0 to 4-bit NormalFloat (NF4) and implements Double Quantization and Paged Optimizers, allowing fine-tuning a 70B LLM on a single 48GB GPU.",
         "LoRA adapters are lightweight (tens of megabytes) and can be swapped dynamically on a shared base model for multi-tenant serving."),

        ("iv-aiml-110", "AI & Machine Learning", "Intermediate", "Pinecone",
         "Explain the architecture of a Production Retrieval-Augmented Generation (RAG) system and the role of Vector Databases.",
         "LLMs suffer from knowledge cutoffs and hallucinations. RAG grounds LLM generation in external, verified proprietary knowledge without expensive model retraining.",
         "Production Architecture Pipeline:<br>1. Ingestion Phase: Documents are loaded, cleaned, and split using semantic recursive chunking (e.g., 512 tokens with 50-token overlap). An embedding model (e.g., `text-embedding-3-large`, `bge-large`) converts chunks into dense vector embeddings.<br>2. Vector Database Indexing: Stored in a vector database (Pinecone, Milvus, Qdrant, pgvector) using Approximate Nearest Neighbor (ANN) index structures like HNSW (Hierarchical Navigable Small World graphs) or IVFFlat.<br>3. Query & Retrieval Phase: User query is embedded using the exact same embedding model. Vector DB performs cosine/dot-product similarity search to retrieve top-K candidate chunks.<br>4. Re-Ranking Phase: A cross-encoder Re-Ranker (e.g., Cohere Rerank) scores retrieved chunks against query to filter noise.<br>5. Generation Phase: Formatted prompt containing retrieved verified context and query is fed to LLM with instructions to answer strictly based on provided facts.",
         "Hybrid Search (combining BM25 sparse keyword search with dense vector embeddings via Reciprocal Rank Fusion) significantly outperforms pure vector search for domain-specific terminology."),

        ("iv-aiml-111", "AI & Machine Learning", "Advanced", "Tri Dao",
         "What is FlashAttention and how does IO-aware tiling overcome the GPU Memory Bandwidth bottleneck?",
         "Standard Multi-Head Attention computes intermediate matrices of size (N x N), where N is sequence length. For long contexts, attention is memory-bandwidth bound, NOT compute bound.",
         "The Hardware Bottleneck: Modern GPUs (A100/H100) have massive high-bandwidth memory (HBM, 80GB at 2 TB/s) and ultra-fast on-chip SRAM (192KB per SM at 19 TB/s). Standard attention writes the intermediate (N x N) attention matrix S = Q*K^T and P = softmax(S) back to slow HBM, then reads it back to compute P*V. For N = 32k, this matrix consumes gigabytes of memory and saturates HBM bandwidth.<br>FlashAttention Innovations (Dao et al.):<br>1. Tiling: Loads blocks of Q, K, V into fast on-chip SRAM, computes attention entirely within SRAM, and writes only the final output back to HBM.<br>2. Online Softmax: Standard softmax requires computing the row-wise max and sum of exponentials across the entire sequence. FlashAttention uses online softmax (Milakov & Gimelshein) to incrementally rescale and update running softmax values block-by-block without storing the full (N x N) matrix.<br>3. Recomputation: During backward pass, instead of saving the giant (N x N) attention matrix from forward pass, it recomputes attention on-the-fly in SRAM, which is faster than reading it from slow HBM.",
         "FlashAttention yields a 2x to 4x wall-clock speedup and reduces memory complexity from O(N^2) to linear O(N)."),

        ("iv-aiml-112", "AI & Machine Learning", "Fresher", "Meta",
         "Explain LLM Generation Decoding: Compare Greedy Search, Beam Search, Temperature, Top-K, and Top-P (Nucleus) Sampling.",
         "At each generation step, an LLM outputs unnormalized logits across its entire vocabulary (typically 32k to 128k tokens), which softmax converts into a probability distribution.",
         "1. Greedy Search: Always picks the single token with highest probability (`argmax`). Deterministic, but repetitive and prone to getting stuck in unnatural loops.<br>2. Beam Search: Maintains the top B most probable sequence candidates ('beams') at each step. Excellent for machine translation and summarization, but produces dull, robotic text for open-ended creative generation.<br>3. Temperature (T): Scales logits before softmax: P(x_i) = exp(z_i / T) / Sum exp(z_j / T).<br>- Low Temperature (T -> 0.1): Sharpens distribution toward highest probability tokens; output is focused, conservative, deterministic.<br>- High Temperature (T -> 1.5): Flattens distribution toward uniform; increases diversity and creativity, but risks hallucinations and nonsensical grammar.<br>4. Top-K Sampling: Truncates vocabulary to strictly the top K highest-probability tokens (e.g., K = 50), filtering out the long tail of bizarre tokens.<br>5. Top-P (Nucleus) Sampling: Dynamically selects the smallest set of tokens whose cumulative probability exceeds threshold P (e.g., P = 0.9). Adapts to distribution sharpness: when the model is confident, the nucleus contains 1 token; when uncertain, it expands to 50 tokens.",
         "Standard production default for chat assistants: Temperature = 0.7, Top-P = 0.9."),

        ("iv-aiml-113", "AI & Machine Learning", "Intermediate", "DeepMind",
         "Compare Reinforcement Learning from Human Feedback (RLHF) with Direct Preference Optimization (DPO).",
         "Pre-trained LLMs predict the next word; post-training alignment (RLHF/DPO) aligns models to be helpful, honest, and harmless.",
         "1. Traditional RLHF (3-Step Pipeline):<br>- Step 1: Supervised Fine-Tuning (SFT) on high-quality demonstration datasets.<br>- Step 2: Reward Model Training: Humans rank multiple model completions; train a scalar Reward Model r_phi(x, y) using Bradley-Terry preference loss.<br>- Step 3: RL Fine-Tuning: Use Proximal Policy Optimization (PPO) to train the policy LLM to maximize reward while penalizing KL divergence drift from the original SFT model.<br>Challenges: PPO is notoriously unstable, sensitive to hyperparameters, and requires loading 4 models simultaneously in VRAM (Actor, Critic, Reward, Reference).<br>2. Direct Preference Optimization (DPO, Rafailov et al.):<br>Mathematical insight: The optimal policy in the constrained RL objective can be solved analytically! The implicit reward function can be expressed directly in terms of the policy probability ratio: r(x, y) = beta * log( pi_theta(y|x) / pi_ref(y|x) ).<br>By substituting this back into the Bradley-Terry objective, DPO optimizes the policy LLM directly on paired preference data (`(prompt, chosen, rejected)`) using a simple cross-entropy loss with ZERO reinforcement learning, zero reward model, and zero actor-critic training!",
         "DPO has largely superseded PPO in open-source fine-tuning due to its training stability and low compute overhead."),

        ("iv-aiml-114", "AI & Machine Learning", "Intermediate", "Tesla",
         "Compare Convolutional Neural Networks (CNNs) with Vision Transformers (ViT) in terms of Inductive Bias and data scale.",
         "CNNs and ViTs represent two competing architectural paradigms in computer vision.",
         "1. CNNs (e.g., ResNet, ConvNeXt): Built upon strong Inductive Biases:<br>- Translation Invariance: Shifting an object in an image does not change feature representation.<br>- Locality: Pixels close together in space are strongly correlated; early layers extract local edges/textures via small 3x3 receptive fields.<br>Because of these strong inductive biases, CNNs learn very efficiently on small to medium datasets (ImageNet-1k) and train stably.<br>2. Vision Transformers (ViT, Dosovitskiy et al.): Flattens an image into non-overlapping 16x16 pixel patches, projects each patch linearly into an embedding vector, prepends a learnable `[CLS]` token, adds 1D positional embeddings, and feeds them into standard Transformer encoder blocks.<br>Zero Inductive Bias: ViT has NO prior knowledge of 2D image topology! Every patch can attend to every other patch across the entire image from layer 1.<br>Data Scale Scaling Law: On small datasets, ViT underperforms CNNs due to lack of inductive bias. But when pre-trained on massive datasets (JFT-300M, LAION), ViT surpasses CNNs by learning richer, more flexible global representations without inductive saturation.",
         "Modern hybrid models (e.g., Swin Transformer) reintroduce hierarchical local window attention to combine both advantages."),

        ("iv-aiml-115", "AI & Machine Learning", "Advanced", "Runway",
         "Explain Diffusion Models (DDPM) for image generation: Compare Forward Diffusion with Reverse Denoising.",
         "Diffusion models generate photorealistic images by learning to reverse a gradual noising process.",
         "1. Forward Diffusion Process (Fixed, Markov Chain): Gradually adds tiny amounts of Gaussian noise to an image x_0 over T timesteps (typically T = 1,000) according to a variance schedule beta_t: q(x_t | x_(t-1)) = N(x_t; sqrt(1 - beta_t)*x_(t-1), beta_t * I).<br>Reparameterization Trick: The noisy image at ANY arbitrary step t can be sampled directly in closed form: x_t = sqrt(alpha_bar_t) * x_0 + sqrt(1 - alpha_bar_t) * epsilon, where epsilon ~ N(0, I). At t = T, the image is indistinguishable from pure white noise.<br>2. Reverse Denoising Process (Learned): A neural network (typically a U-Net with cross-attention for text conditioning) is trained to predict the added noise epsilon_theta(x_t, t) at each step by minimizing simple MSE loss: Loss = || epsilon - epsilon_theta(x_t, t) ||^2.<br>3. Sampling: Start with pure random noise x_T ~ N(0, I). Iteratively subtract predicted noise step-by-step for T steps until a pristine, high-resolution image x_0 emerges.",
         "Latent Diffusion Models (Stable Diffusion) run diffusion inside a compressed latent space encoded by a VAE, reducing compute requirements by 64x compared to pixel-space diffusion."),

        ("iv-aiml-116", "AI & Machine Learning", "Intermediate", "Nvidia",
         "What is Quantization in Deep Learning: Compare Post-Training Quantization (PTQ) with Quantization-Aware Training (QAT).",
         "Deep learning models typically train in 32-bit floating point (FP32) or 16-bit brain floating point (BF16). Quantization converts weights and activations to lower-precision integers (INT8 or INT4) to slash memory and accelerate tensor core throughput.",
         "Mapping Function: Maps a continuous float x in [alpha, beta] to integer q: q = round(x / S) + Z, where S is the Scale factor and Z is the Zero-point.<br>1. Post-Training Quantization (PTQ): Quantizes a pre-trained model directly without retraining. Uses a small calibration dataset to record dynamic activation ranges and calculate optimal clipping thresholds. Fast (takes minutes), but can suffer noticeable accuracy degradation in sub-8-bit regimes (INT4) due to activation outliers.<br>2. Quantization-Aware Training (QAT): Simulates quantization errors during training/fine-tuning using 'fake quantization' nodes. Forward pass clips and rounds weights/activations to INT8; backward pass uses Straight-Through Estimator (STE) to propagate gradients past non-differentiable rounding operators. The model adapts its weights to be resilient to quantization noise, achieving near-zero accuracy loss.",
         "Advanced LLM PTQ algorithms: AWQ (Activation-aware Weight Quantization) and GPTQ protect salient outlier weights in FP16 while quantizing the remaining 99% of weights to 4-bit."),

        ("iv-aiml-117", "AI & Machine Learning", "Fresher", "Uber",
         "What is the difference between Batch Normalization and Layer Normalization, and why do Transformers use LayerNorm?",
         "Normalization stabilizes hidden state distributions, enabling higher learning rates and faster training convergence.",
         "1. Batch Normalization (BatchNorm): Normalizes activations ACROSS THE BATCH dimension for each individual feature channel: Mean and variance are computed across (N, H, W).<br>Why BatchNorm fails in NLP/Transformers:<br>- Sequences have variable lengths, requiring padding tokens that corrupt batch statistics.<br>- At inference, BatchNorm relies on running mean/variance tracked during training; under batch size = 1 (streaming inference), it behaves poorly.<br>2. Layer Normalization (LayerNorm): Normalizes activations ACROSS ALL FEATURES for each individual sample independently: Mean and variance are computed across the feature dimension (d_model).<br>Why Transformers use LayerNorm: LayerNorm is completely independent of batch size and batch sequence lengths. It operates identically during training and single-token autoregressive generation.",
         "Pre-LayerNorm (applying LayerNorm BEFORE attention and FFN blocks) has replaced Post-LayerNorm in modern LLMs (Llama, GPT-3) because it eliminates warm-up requirements and guarantees stable gradient propagation."),

        ("iv-aiml-118", "AI & Machine Learning", "Intermediate", "Scale AI",
         "What is Data Drift versus Concept Drift in production ML systems, and how do you detect and monitor them?",
         "Production ML models degrade over time because real-world data distributions change continuously.",
         "1. Data Drift (Covariate Shift): The distribution of input features P(X) changes over time, while the conditional relationship between inputs and ground truth P(Y | X) remains unchanged. Example: An e-commerce recommendation model experiences a demographic shift from college students to retirees.<br>- Detection: Compare baseline training feature distributions against live production inference data using statistical tests: Kolmogorov-Smirnov (KS) test for continuous variables; Population Stability Index (PSI, alert if PSI > 0.2); Wasserstein Distance.<br>2. Concept Drift: The underlying relationship between input features and ground truth P(Y | X) changes, even if input distribution P(X) looks identical. Example: A credit card fraud model: fraudulent transaction patterns change abruptly as scammers adapt new tactics; or pre-COVID vs post-COVID shopping behavior.<br>- Detection: Monitoring ground-truth model performance metrics (Accuracy, F1-score, Precision/Recall) over sliding time windows.",
         "Automated re-training triggers and shadow model deployments are standard MLOps practices to counter drift."),

        ("iv-aiml-119", "AI & Machine Learning", "Advanced", "OpenAI",
         "Explain the KV Cache in Transformer inference and calculate its memory consumption for a 70B parameter model.",
         "During autoregressive LLM decoding, the model generates one token at a time. Without caching, each new token requires recomputing Keys and Values for all preceding tokens, resulting in O(N^2) redundant computation.",
         "KV Cache Mechanism: In self-attention, token i needs to attend to Keys and Values of all tokens 0 to i. Because past tokens do not change, their computed Key and Value vectors can be cached in GPU VRAM after their first computation. Each new decoding step computes Q, K, V ONLY for the single newest token, appends the new K and V to the cache, and computes attention against the cached KV tensors in O(N) time.<br>Memory Calculation for Llama-2-70B:<br>Parameters: Layers L = 80, Hidden Dim d = 8192, Context Length N = 4096, Batch Size B = 1.<br>Using Grouped-Query Attention (GQA) with 8 KV heads (dimension 8 * 128 = 1024):<br>Bytes per token = 2 (for FP16) * 2 (Keys and Values) * L * (d_kv) = 4 * 80 * 1024 = 327,680 bytes (~320 KB per token).<br>For 4,096 tokens: 320 KB * 4,096 approx 1.31 GB per concurrent user request! For a batch size of 32 concurrent streams, the KV cache alone consumes ~42 GB of GPU VRAM!",
         "PagedAttention (vLLM) manages KV cache memory like virtual memory paging to eliminate fragmentation and boost serving throughput by 2x to 4x."),

        ("iv-aiml-120", "AI & Machine Learning", "Intermediate", "Cohere",
         "Compare Cross-Encoders and Bi-Encoders in semantic search and information retrieval.",
         "Both are neural ranking architectures used in natural language processing and semantic search.",
         "1. Bi-Encoder (Dense Retrieval): Encodes query Q and document D independently into two dense vector embeddings using a shared transformer: `v_q = Model(Q)` and `v_d = Model(D)`. The similarity score is the dot product `v_q . v_d`.<br>Advantage: Document vectors can be pre-computed offline and indexed in a Vector Database. At query time, only the short query is embedded, and similarity search runs in sub-milliseconds across millions of documents via HNSW index. Disadvantage: Cannot model token-level interactions between query and document.<br>2. Cross-Encoder (Re-Ranker): Feeds query and document SIMULTANEOUSLY into a single transformer: `Score = Model([CLS] Query [SEP] Document [SEP])`. Full self-attention operates across all query tokens and document tokens jointly from layer 1.<br>Advantage: Exceptional retrieval accuracy and semantic nuance. Disadvantage: Cannot pre-compute embeddings; evaluating 1,000 documents requires running 1,000 full forward passes through a heavy transformer (hundreds of milliseconds).",
         "The standard production pattern: Bi-Encoder retrieves top-100 candidates in 5 ms; Cross-Encoder re-ranks top-100 down to top-5 in 30 ms."),
    ]
    
    for item in data:
        qid, sub, diff, comp, q, c, t, tip = item
        qs[qid] = {
            "cat": "Technical",
            "track": "aiml",
            "sub": sub,
            "diff": diff,
            "company": comp,
            "q": q,
            "a": make_tech_ans(c, t, tip)
        }
    return qs
